<?php
declare(strict_types=1);
$sessionPath=dirname(__DIR__).'/storage/cache';
if(!is_dir($sessionPath))mkdir($sessionPath,0775,true);
ini_set('session.save_path',$sessionPath);
require dirname(__DIR__).'/bootstrap.php';
use Cbt\Core\ViewRenderer;
use Cbt\Support\{Id,SecretCipher};
$passed=0;$failed=0;
$test=function(string$name,callable$callback)use(&$passed,&$failed):void{try{$callback();echo"PASS {$name}\n";$passed++;}catch(Throwable$e){echo"FAIL {$name}: {$e->getMessage()}\n";$failed++;}};
$assert=function(bool$condition,string$message='Assertion failed'):void{if(!$condition)throw new RuntimeException($message);};
$test('ULID has stable safe format',function()use($assert){$id=Id::ulid();$assert((bool)preg_match('/^[0-9A-HJKMNP-TV-Z]{26}$/',$id));});
$test('Password hash never equals plaintext',function()use($assert){$plain='TeacherPassword#2026';$hash=password_hash($plain,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT);$assert($hash!==$plain);$assert(password_verify($plain,$hash));$assert(!password_verify('wrong',$hash));});
$test('PIN encryption round trip',function()use($assert){putenv('APP_KEY=test-only-key-which-is-longer-than-32-characters');$_ENV['APP_KEY']='test-only-key-which-is-longer-than-32-characters';$cipher=new SecretCipher();$encrypted=$cipher->encrypt('012345');$assert($encrypted!=='012345');$assert($cipher->decrypt($encrypted)==='012345');});
$test('Schema protects NISN and answer/result uniqueness',function()use($assert){$schema=file_get_contents(dirname(__DIR__).'/database/schema.sql')?:'';$assert(str_contains($schema,'UNIQUE KEY uq_students_nisn (nisn)'));$assert(str_contains($schema,'UNIQUE KEY uq_answer_attempt_question (attempt_id,question_id)'));$assert(str_contains($schema,'UNIQUE KEY uq_results_attempt (attempt_id)'));$assert(!preg_match('/\bnomor_ujian\b/i',$schema));});
$test('Portal secret absent from browser JavaScript',function()use($assert){$files=new RecursiveIteratorIterator(new RecursiveDirectoryIterator(dirname(__DIR__).'/public/assets/js'));foreach($files as$file){if($file->getExtension()==='js')$assert(!str_contains((string)file_get_contents($file->getPathname()),'PORTAL_DATA_API_KEY'),'Portal API key referenced by browser asset');}});
$test('Resume payload restores flagged answers and server clock',function()use($assert){$adapter=(string)file_get_contents(dirname(__DIR__).'/public/assets/js/native-api-adapter.js');$exam=(string)file_get_contents(dirname(__DIR__).'/public/assets/js/cbt/exam-session.js');$assert(str_contains($adapter,'ragu:!!Number(a.is_flagged)'));$assert(str_contains($adapter,'serverTime:r.data.server_time'));$assert(str_contains($exam,'if (j.ragu) stRagu[j.soal_id] = true'));$assert(str_contains($exam,'clockOffset'));});
$test('Admin exam list rejects teacher role',function()use($assert){$routes=(string)file_get_contents(dirname(__DIR__).'/public/index.php');$assert(str_contains($routes,"\$router->get('/api/admin/exams',[\$admin,'exams'],[\$adminAuth]);"));});
$test('Portal sync exposes admin status and reconciles stale cache',function()use($assert){$routes=(string)file_get_contents(dirname(__DIR__).'/public/index.php');$service=(string)file_get_contents(dirname(__DIR__).'/app/Services/PortalDataSyncService.php');$assert(str_contains($routes,"/api/admin/portal-data/sync/status"));$assert(str_contains($service,"if(\$status==='SUCCESS')"));$assert(str_contains($service,'deactivateStale'));});
$test('Portal academic references drive exams and assignments',function()use($assert){$schema=(string)file_get_contents(dirname(__DIR__).'/database/schema.sql');$repo=(string)file_get_contents(dirname(__DIR__).'/app/Repositories/AdminRepository.php');$routes=(string)file_get_contents(dirname(__DIR__).'/public/index.php');$assert(str_contains($schema,'CREATE TABLE IF NOT EXISTS portal_academic_years'));$assert(str_contains($schema,'CREATE TABLE IF NOT EXISTS portal_semesters'));$assert(str_contains($repo,"FROM teachers WHERE status='ACTIVE'"));$assert(str_contains($repo,'portal_academic_year_id=:year'));$assert(str_contains($routes,'/api/admin/portal-data/references'));});
$test('Teacher authentication route is SSO only',function()use($assert){$routes=(string)file_get_contents(dirname(__DIR__).'/public/index.php');$view=(string)file_get_contents(dirname(__DIR__).'/resources/views/teacher/login.php');$assert(!str_contains($routes,"/api/auth/teacher/login"));$assert(str_contains($routes,"/auth/sso/start"));$assert(str_contains($view,'Masuk dengan Portal Data'));});
$test('Subject catalog seed drives exam assignments',function()use($assert){$schema=(string)file_get_contents(dirname(__DIR__).'/database/schema.sql');$seed=(string)file_get_contents(dirname(__DIR__).'/database/seed.php');$repo=(string)file_get_contents(dirname(__DIR__).'/app/Repositories/AdminRepository.php');$assert(str_contains($schema,'CREATE TABLE IF NOT EXISTS subjects'));$assert(str_contains($schema,'fk_exams_subject'));foreach(['BIO','KIM','FIS','MTKW','QH','PJOK','BK']as$code)$assert(str_contains($seed,"'{$code}'"),"Mapel {$code} tidak ada di seed");$assert(str_contains($repo,'s.name nama_mapel'));});
$test('Browser refresh restores authenticated state',function()use($assert){$staff=(string)file_get_contents(dirname(__DIR__).'/public/assets/js/cbt/staff-session.js');$adapter=(string)file_get_contents(dirname(__DIR__).'/public/assets/js/native-api-adapter.js');$auth=(string)file_get_contents(dirname(__DIR__).'/app/Services/AuthService.php');$assert(str_contains($staff,"fetch('api/auth/me'"));$assert(str_contains($staff,"status_pengerjaan === 'berlangsung'"));$assert(str_contains($adapter,"IN_PROGRESS:'berlangsung'"));$assert(str_contains($auth,'sessionState'));});
$test('CBT frontend is split into maintainable domain modules',function()use($assert){$html=(string)file_get_contents(dirname(__DIR__).'/index.html');$directory=dirname(__DIR__).'/public/assets/js/cbt';$modules=glob($directory.'/*.js')?:[];$assert(count($modules)>=10,'Frontend modules are missing');$assert(!is_file(dirname(__DIR__).'/public/assets/js/cbt-app.js'),'Legacy monolith still exists');foreach($modules as$module){$assert(substr_count((string)file_get_contents($module),"\n")<700,basename($module).' is too large');$assert(str_contains($html,'assets/js/cbt/'.basename($module)),basename($module).' is not loaded');}});
$test('CBT view shell renders modular partials',function()use($assert){$root=dirname(__DIR__);$shell=(string)file_get_contents($root.'/index.html');$html=(new ViewRenderer($root.'/resources/views/app'))->render($shell);$assert(!str_contains($html,'{{>'),'Unresolved view partial remains');$assert(str_contains($html,'id="viewLoginSiswa"'));$assert(str_contains($html,'id="viewDashboardPengelola"'));$assert(str_contains($html,'id="modalSubmitUjian"'));});
$test('Local HTTP keeps session cookie while production can require Secure',function()use($assert){$session=(string)file_get_contents(dirname(__DIR__).'/app/Core/Session.php');$assert(str_contains($session,"&&\$https"));$assert(str_contains($session,"session.gc_maxlifetime"));$assert(str_contains($session,"session.use_strict_mode"));});
$test('Teacher live sessions are scoped and expose progress only',function()use($assert){$routes=(string)file_get_contents(dirname(__DIR__).'/public/index.php');$repo=(string)file_get_contents(dirname(__DIR__).'/app/Repositories/AdminRepository.php');$service=(string)file_get_contents(dirname(__DIR__).'/app/Services/AdminService.php');$view=(string)file_get_contents(dirname(__DIR__).'/resources/views/teacher/dashboard.php');$js=(string)file_get_contents(dirname(__DIR__).'/public/assets/js/teacher/live-sessions.js');$assert(str_contains($routes,"/api/teacher/live-sessions"));$assert(str_contains($routes,"\$teacherAuth"));$assert(str_contains($repo,'teacherExamIds'));$assert(str_contains($repo,'answeredQuestions'));$assert(str_contains($repo,"status IN ('IN_PROGRESS','TERMINATED')"));$assert(str_contains($service,'teacherLiveSessions'));$assert(str_contains($view,'data-section="live"'));$assert(str_contains($js,'setTimeout(load, 10000)'));$assert(!str_contains($js,'correct_answer'));});
echo"\n{$passed} passed, {$failed} failed.\n";exit($failed===0?0:1);
